['```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <forward_list>
#include <functional>
#include <mutex>
#include <shared_ptr>
#include <thread>
#include <atomic>
#include <stdexcept>
#include <iterator>

class Logger {
public:
    virtual void log(const std::string& message) = 0;
};

class ConsoleLogger : public Logger {
public:
    void log(const std::string& message) override {
        std::cout << "[" << this->getThreadId() << "] " << message << "\n";
    }

private:
    int getThreadId() const {
        return std::this_thread::get_id();
    }
};

class FileLogger : public Logger {
public:
    explicit FileLogger(const std::string& filePath) : m_file(filePath, std::ios::out | std::ios::app) {}

    void log(const std::string& message) override {
        m_mutex.lock();
        m_file << "[" << this->getThreadId() << "] " << message << "\n";
        m_mutex.unlock();
    }

private:
    std::ofstream m_file;
    std::mutex m_mutex;
    int getThreadId() const {
        return std::this_thread::get_id();
    }
};

class StringListManager {
public:
    void insertAfterOrLogError(const std::string& key, const std::string& value, std::shared_ptr<Logger> logger) {
        std::unique_lock<std::mutex> lock(m_listMutex);
        auto it = m_strings.begin();
        bool found = false;

        for (; it != m_strings.end() && !found; ++it) {
            if (*it == key) {
                found = true;
                it.next()->insert_after(it, value);
                lock.unlock();
                return;
            }
        }

        if (!found) {
            m_strings.emplace_back(value);
            lock.unlock();
            logger->log("Key not found, appending value: " + value);
        }
    }

private:
    std::forward_list<std::string> m_strings;
    mutable std::mutex m_listMutex;
};

// Test cases
int main() {
    auto logger = std::make_shared<ConsoleLogger>();
    StringListManager manager(logger);

    // Simple test
    manager.insertAfterOrLogError("test", "hello");
    manager.insertAfterOrLogError("test2", "world");

    for (auto&& str : manager) {
        std::cout << str << "\n";
    }

    // Concurrent access test
    auto logger2 = std::make_shared<ConsoleLogger>();
    StringListManager concurrentManager(logger2);

    std::thread t1([&concurrentManager]() {
        concurrentManager.insertAfterOrLogError("test", "concurrency");
    });

    concurrentManager.insertAfterOrLogError("test2", "concurrent world");

    t1.join();

    for (auto&& str : concurrentManager) {
        std::cout << str << "\n";
    }

    return 0;
}
```']

