        {
            _logger = logger;
            _dbConnection = dbConnection;
            _cdnService = cdnService;
        }

        public async Task<IActionResult> UpdatePageContent(string pageSectionId, string elementId, string htmlContent)
        {
            if (string.IsNullOrWhiteSpace(pageSectionId) || string.IsNullOrWhiteSpace(elementId) || string.IsNullOrWhiteSpace(htmlContent))
                return new BadRequestObjectResult("All parameters are required.");

            if (!Regex.IsMatch(pageSectionId, @"^[a-zA-Z0-9_-]+$"))
                return new BadRequestObjectResult("Invalid page section ID format.");

            if (!Regex.IsMatch(elementId, @"^[a-zA-Z0-9_-]+$"))
                return new BadRequestObjectResult("Invalid element ID format.");

            using var transaction = _dbConnection.BeginTransaction();

            try
            {
                // Update database with the HTML content and page section id for the given element id

                transaction.Commit();

                // Invalidate the CDN cache for the updated page section
                await _cdnService.InvalidateCache(pageSectionId);

                return new OkObjectResult(new { Success = true });
