            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating page content");

                transaction.Rollback();

                // Handle error and return appropriate HTTP status code and message
                return new StatusCodeResult((int)HttpStatusCode.InternalServerError);
            }
