  try {
    return await promise;
  } catch (error) {
    if (!attemptsLeft) throw error;

    const delay = Math.min(
      Math.max((Math.pow(2, attemptsLeft - 1)) * MIN_RETRY_DELAY, MIN_RETRY_DELAY),
      MAX_RETRY_DELAY
    );

    console.log(`Retrying in ${delay}ms due to error...`);
    await new Promise((resolve) => setTimeout(resolve, delay));

    return retry(promise, attemptsLeft - 1);
  }
};

// Main function for processing log files asynchronously.
