['```java
import java.nio.channels.*;
import org.apache.kafka.clients.producer.*;
import com.rabbitmq.client.*;

public class ResilientConnectionManager {
    private static final String KAFKA_TOPIC = "connection-status";
    private static final String RABBITMQ_EXCHANGE = "connection-events";

    private ExecutorService executor;
    private Selector selector;
    private ThreadPoolExecutor statusProducer;
    private Connection connection;
    private Channel channel;

    public ResilientConnectionManager() {
        // Initialize Kafka and RabbitMQ producers
        KafkaProducerFactory<String, String> kafkaProducerFactory = createKafkaProducerFactory();
        statusProducer = new ThreadPoolExecutor(5, 10, 60L, TimeUnit.SECONDS, new LinkedBlockingQueue<>(100));
        statusProducer.submit(() -> createKafkaAndRabbitMQProducers(kafkaProducerFactory));

        // Initialize NIO Channels
        executor = Executors.newCachedThreadPool();
        selector = Selector.open();
    }

    private void createKafkaAndRabbitMQProducers(KafkaProducerFactory<String, String> kafkaProducerFactory) {
        // Initialize RabbitMQ connection and channel
        ConnectionFactory factory = new ConnectionFactory();
        try {
            connection = factory.newConnection();
            channel = connection.createChannel();
        } catch (Exception e) {
            logError("Failed to initialize RabbitMQ producers", e);
        }

        // Initialize Kafka producer
        Producer<String, String> kafkaProducer = kafkaProducerFactory.create();
        sendConnectionStatus(kafkaProducer, "established");
        new ConnectionEstablishmentTask(kafkaProducer).start();
    }

    private void sendConnectionStatus(Producer<String, String> producer, String status) {
        // Send connection event to Kafka and RabbitMQ
        ProducerRecord<String, String> kafkaRecord = new ProducerRecord<>(KAFKA_TOPIC, status);
        producer.send(kafkaRecord, (metadata, exception) -> {
            if (exception == null) {
                sendToRabbitMQ(status);
            } else {
                logError("Failed to send connection event to Kafka", exception);
            }
        });
    }

    private void sendToRabbitMQ(String status) {
        // Send connection event to RabbitMQ
        BasicProperties props = new BasicProperties.Builder()
                .contentType("application/json").build();
        channel.basicPublish(RABBITMQ_EXCHANGE, "", props, status.getBytes());
    }

    // Implement other methods for handling connections, reconnection strategies, error handling, backpressure, etc.
}
```

This code provides a basic structure for the resilient connection manager using Java NIO Channels with Kafka and RabbitMQ integration. It initializes the producers and starts a new thread pool to create and maintain connections. The `sendConnectionStatus()` method is used to report connection status events, and the `createKafkaAndRabbitMQProducers()` method sets up the RabbitMQ connection and channel along with the Kafka producer.

You can further expand this code by implementing connection handling, error management, reconnection strategies, backpressure mechanisms, and other functionalities based on your requirements. Make sure to test each component thoroughly and document the implementation for future maintenance.']

