}

// RateLimiter.php
class RateLimiter {
    private $delay;

    public function __construct($requestsPerMinute, $delay = 5) {
        $this->delay = $delay;
        $this->countdown = max(0, $requestsPerMinute * $delay);
    }

    public function allow() {
        if ( $this->countdown <= 0 ) {
            $this->countdown += self::REQUEST_INTERVAL;
            return true;
        }

        return false;
    }
}

// RequestInterval.php (constant)
define('REQUEST_INTERVAL', 1); // seconds
