import requests

app = Flask(__name__)
config = {
    'development': {
        'DB_URI': os.getenv('DEVELOPMENT_DB_URI'),
        'API_KEY': os.getenv('API_KEY')
    },
    'staging': {
        'DB_URI': os.getenv('STAGING_DB_URI'),
        'API_KEY': os.getenv('API_KEY_STAGING')
    },
    'production': {
        'DB_URI': os.getenv('PRODUCTION_DB_URI'),
        'API_KEY': os.getenv('API_KEY_PRODUCTION')
    }
}

# Database connection pool and session maker
engine = create_engine(config[os.environ.get('ENVIRONMENT', 'development')]['DB_URI'], pool_size=5, max_overflow=0)
Session = sessionmaker(bind=engine)

# External API client for department details
def get_department_details(employee_id):
    headers = {'Authorization': config[os.environ.get('ENVIRONMENT', 'development')]['API_KEY']}
    response = requests.get(f'https://api.example.com/departments/{employee_id}', headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        return None

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/employees', methods=['POST'])
def get_employees():
    data = request.get_json()
    supervisor_id = data['supervisor_id']

    with Session() as session:
        employees = session.execute("SELECT * FROM employees WHERE supervisor_id = :supervisor_id", {'supervisor_id': supervisor_id}).fetchall()

    employee_list = []
    for employee in employees:
        details = get_department_details(employee[1])  # Accessing the second column, which represents the employee id
        if details is not None:
            employee_list.append({'id': employee[0], 'name': employee[1], 'department': details['department']})

    return jsonify(employee_list)
```

