['1. **Background Process Management (C)**

```c
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

// Define a semaphore for process synchronization
sem_t g_process_sync;

pid_t spawn_command(const char *cmd) {
    pid_t pid = fork();
    if (pid == -1) {
        // Handle fork failure
        return 0;
    } else if (pid > 0) {
        // Parent process
        sem_post(&g_process_sync);
        return pid;
    } else {
        // Child process
        execl(cmd, cmd, NULL);
        // Execution failed
        exit(1);
    }
}

void manage_background_tasks() {
    while (true) {
        pid_t pid = spawn_command("your-command");

        sem_wait(&g_process_sync);

        if (waitpid(pid, NULL, WNOHANG) > 0) {
            // Clean up resources for completed process
            cleanup(pid);
        }
    }
}
```

