struct AttackConfig {
    std::string name;
    double probability;
    int cooldown;
    std::string api_url;
};

// Error logging macro
#define LOG_ERROR(msg) std::cerr << "[Error] " << msg << std::endl

std::mutex log_mutex;
void log_attack(const AttackConfig& attack, time_t last_attack, double elapsed) {
    std::lock_guard<std::mutex> lock(log_mutex);
    auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
    std::cout << "[Log] " << attack.name << ", elapsed: " << elapsed << ", last used: " << ctime(&last_attack)
              << ctime(&now) << " (difference: " << now - last_attack << " sec)" << std::endl;
}

// Attack function, handles API call with retry logic and cooldown management
void attack(AttackConfig& attack, time_t* last_use, const boost::asio::io_service& io_service) {
    // Retry logic (up to 3 times)
    for (int i = 0; i < 3 || !has_connection_failed(); ++i) {
        CURL *curl = curl_easy_init();
        if (!curl) continue;

        curl_easy_setopt(curl, CURLOPT_URL, attack.api_url.c_str());
        // Configure network latency (500ms to 2000ms)
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(500, 2000);
        auto delay = dis(gen);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, delay + 1000); // Add a margin of error for timing

        // Perform API call and process response
        CURLcode res;
        std::stringstream buffer;
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](char *buffer, size_t size, size_t nmemb, void *userp) {
            auto ss = static_cast<std::stringstream*>(userp);
            ss->write(buffer, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &buffer);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            LOG_ERROR("API request failed with error: " << curl_easy_strerror(res));
            continue;
        }

        // Parse API response, select attack strategy and update cooldown
        nlohmann::json json = nlohmann::json::parse(buffer.str());
        // Implement logic for selecting attack strategy based on parsed JSON data

        curl_easy_cleanup(curl);
    }

    std::lock_guard<std::mutex> lock(*last_use);
    *last_use = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
}

// Modular C++ function that manages the selection and cooldown of two attack strategies
void selectAttack(const std::vector<AttackConfig>& attacks, time_t* last_use1, time_t* last_use2, const boost::asio::io_service& io_service) {
    // Ensure one attack has expired before selecting it (if not explicitly overridden in the config)
    if (std::chrono::system_clock::now() - *last_use1 >= std::chrono::seconds(attacks[1].cooldown)) {
        attacks[1].probability += 1.0; // Override with a higher probability to ensure selection
    } else if (std::chrono::system_clock::now() - *last_use2 >= std::chrono::seconds(attacks[0].cooldown)) {
        attacks[0].probability += 1.0; // Override with a higher probability to ensure selection
    }

    auto total = attacks[0].probability + attacks[1].probability;
    double prob0 = attacks[0].probability / total, prob1 = attacks[1].probability / total;

    std::uniform_real_distribution<> dist(0.0, 1.0);
    if (dist(rd) <= prob0) {
        attack(attacks[0], last_use1, io_service);
    } else {
        attack(attacks[1], last_use2, io_service);
    }
}

// Signal handler for catching connection failures and terminating the program gracefully
void signal_handler(int signum) {
    std::cout << "Received signal: " << signum << ", terminating program" << std::endl;
    // Add code to clean up resources, stop threads, etc.
    std::exit(0);
}
