        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            mimeTypeResponse = "application/octet-stream"; // default MIME type for unrecognized files
        }
        curl_easy_cleanup(curl);
    }

    return mimeTypeResponse;
