// Function to analyze file content and rename it, appending unique identifier and timestamp
void renameFile(const std::string &filePath) {
    std::ifstream ifs(filePath, std::ios::binary | std::ios::ate);
    auto size = ifs.tellg();
    auto sha256 = Sha256(ifs, static_cast<unsigned int>(size));
    ifs.seekg(0);

    // Generate unique identifier and timestamp for filename
    std::string uniqueId = "file_" + std::to_string(std::hash<std::string>{}(filePath));
    auto timestamp = std::chrono::system_clock::now().time_since_epoch().count();
    std::string newFileName = uniqueId + "_" + std::to_string(timestamp) + "_";

    // Append MIME type to the new filename
    std::string mimeType = getMimeType(filePath);
    newFileName += mimeType.substr(0, 8) + ".";

    // Ensure valid characters in the filename
    std::regex validChars("[\\w\\.-]+");
    if (!std::regex_match(newFileName, validChars)) {
        newFileName = "invalid_" + newFileName;
    }

    // Rename the file synchronously or asynchronously based on requirements
    // Use a mutex to ensure thread safety in multi-threaded server environment
    std::mutex mtx;
    std::unique_lock<std::mutex> lock(mtx);
    ifs.seekp(0);
    ifs.close();
    std::ofstream ofs(newFileName, std::ios::binary | std::ios::trunc);
    lock.unlock();
    if (ofs) {
        std::ifstream inputFile(filePath, std::ios::binary);
        ofs << inputFile.rdbuf();
    }
}

