    def register(self, key: str, factory: Callable[[], Type[Mapping]]):
        self._registry[key] = factory

    def get(self, key: str) -> Type[Mapping]:
        return self._registry.get(key, Mapping)()

class JsonTransformer:
    def __init__(self, registry: Registry):
        self.registry = registry
        self.custom_serializer = None

    def load(self, data: str) -> Mapping:
        try:
            return json.loads(data, object_hook=self.deserialize)
        except json.JSONDecodeError as e:
            logger.error(f"Invalid JSON data: {e}")
            raise ValueError("Invalid JSON data")

    def serialize(self, obj: Mapping) -> str:
        if self.custom_serializer is not None:
            return self.custom_serializer(obj)
        return json.dumps(obj, cls=JsonEncoder, default=self.serialize_sensitive)

    def deserialize(self, obj: Any) -> Mapping:
        if isinstance(obj, (list, tuple)):
            return [self.deserialize(item) for item in obj]
        elif isinstance(obj, dict):
            return {key: self.deserialize(value) for key, value in obj.items()}
        elif callable(obj):
            return self.registry.get(obj.__name__)(**obj())
        else:
            return obj

    def serialize_sensitive(self, value: Any) -> Any:
        # Implement custom serialization for sensitive fields
        pass

