2. C Function (using JSON-C library):

```c
#include <json-c/json.h>
#include <stdbool.h>

bool validate_oauth2_access_token(char *json_str) {
    cJSON *root = cJSON_Parse(json_str);
    cJSON *access_token_node, *expires_in_node, *token_type_node;
    bool valid = true;

    if (!root || !cJSON_IsObject(root)) {
        return false;
    }

    access_token_node = cJSON_GetObjectItemCaseSensitive(root, "access_token");
    expires_in_node = cJSON_GetObjectItemCaseSensitive(root, "expires_in");
    token_type_node = cJSON_GetObjectItemCaseSensitive(root, "token_type");

    if (!access_token_node || !expires_in_node || !token_type_node) {
        valid = false;
    } else if (!cJSON_IsString(access_token_node) || !cJSON_IsNumber(expires_in_node) || !cJSON_IsString(token_type_node)) {
        valid = false;
    } else if (strcmp(token_type_node->valuestring, "Bearer") != 0 || expires_in_node->valueint < 0) {
        valid = false;
    }

    cJSON_Delete(root);
    return valid;
}
```']

