#include <stdbool.h>
#include <limits.h>

typedef struct {
    int min, max;
    pthread_mutex_t mutex;
} Range;

Range* create_range(int min, int max) {
    Range* range = malloc(sizeof(Range));
    if (!range) return NULL;
    range->min = min;
    range->max = max;
    pthread_mutex_init(&range->mutex, NULL);
    return range;
}

bool in_range(int value, Range* range) {
    pthread_mutex_lock(&range->mutex);
    bool result = (value >= range->min && value <= range->max);
    pthread_mutex_unlock(&range->mutex);
    return result;
}

