```c
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    int* data;
    size_t length;
    pthread_mutex_t mutex;
} DataBuffer;

DataBuffer* create_buffer(size_t capacity) {
    DataBuffer* buffer = malloc(sizeof(DataBuffer));
    if (!buffer) return NULL;
    buffer->data = calloc(capacity, sizeof(int));
    if (!buffer->data) {
        free(buffer);
        return NULL;
    }
    buffer->length = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    return buffer;
}

void enqueue(DataBuffer* buffer, int value) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->length >= capacity) {
        free(buffer->data);
        buffer->capacity *= 2;
        buffer->data = realloc(buffer->data, buffer->capacity * sizeof(int));
    }
    buffer->data[buffer->length] = value;
    buffer->length++;
    pthread_mutex_unlock(&buffer->mutex);
}

void compute_stats(DataBuffer* buffer) {
    // Implement rolling statistics computation here.
}
```

