#include <atomic>
#include <functional>
#include <sstream>
#include <stdexcept>
#include <boost/asio.hpp>
#include <rapidjson/document.h>
#include <spdlog/spdlog.h>

// Custom Error Handler
class RetryErrorHandler {
public:
    RetryErrorHandler(std::atomic_int retryLimit) : m_retryLimit(retryLimit) {}
    template<typename ExceptionType>
    std::function<void()> wrap(const std::function<void()>& func) {
        return [this, func]() {
            try {
                func();
            } catch (const ExceptionType& e) {
                if (--m_retryLimit > 0) {
                    spdlog::error("Transient error encountered: {}", e.what());
                    std::this_thread::sleep_for(std::chrono::milliseconds(getBackoffFactor()));
                    wrap<ExceptionType>(func)();
                } else {
                    throw;
                }
            }
        };
    }
private:
    int getBackoffFactor() const {
        // Implement backoff strategy based on retry count and system load.
    }
    std::atomic_int m_retryLimit;
};

// Resource Bundle Interface
class IResourceBundle {
public:
    virtual void initialize() = 0;
    virtual void teardown() = 0;
};

// Test Suite Manager
class TestSuiteManager {
public:
    void run(IResourceBundle& resourceBundle, const std::vector<std::function<std::future<void()>>>& testFunctions) {
        m_resourceBundle.initialize();
        m_testResults.clear();
        m_concurrentTestLimit.store(0);
        m_runningTests.reserve(testFunctions.size());

        for (const auto& testFunction : testFunctions) {
            if (!m_concurrentTestLimit.load() < maxConcurrentTests()) {
                // Wait for a running test to complete or slot to become available.
                m_conditionVariable.wait(m_mutex);
            }

            auto wrappedTestFunction = std::move(RetryErrorHandler(maxRetriesPerTest(testFunction))(std::move(testFunction)));
            auto future = std::async(std::launch::async, std::move(wrappedTestFunction));

            m_runningTests.emplace_back(std::move(future));
            ++m_concurrentTestLimit;
        }

        // Wait for all tests to complete.
        for (auto& future : m_runningTests) {
            future.wait();
        }

        m_resourceBundle.teardown();
    }
private:
    int maxConcurrentTests() const {
        // Implement concurrency management logic based on system resources and load.
    }
    int maxRetriesPerTest(const std::function<std::future<void()>>& testFunction) const {
        // Implement retry logic for specific tests based on their expected behavior or resource usage.
    }
    IResourceBundle& m_resourceBundle;
    std::vector<std::future<void()>> m_runningTests;
    std::mutex m_mutex;
    std::condition_variable m_conditionVariable;
    std::atomic_int m_concurrentTestLimit;
    std::vector<TestResult> m_testResults;
};

struct TestResult {
    std::string name;
    std::chrono::duration<double> duration;
    TestOutcome outcome;
};

enum class TestOutcome {
    Passed,
    Failed,
    Retried,
    TimedOut,
    Error
};

// Centralized Logging Interface
class ILogger {
public:
    virtual void log(const std::string& module, const std::string& testName, std::chrono::duration<double> duration, TestOutcome outcome) = 0;
};

// Return the promise resolving to an object containing the requested data.
auto runTests(IResourceBundle& resourceBundle, const std::vector<std::function<std::future<void()>>>& testFunctions) {
    TestSuiteManager manager{resourceBundle};
    manager.run(resourceBundle, testFunctions);

    rapidjson::Document result;
    result.AddArray("testResults");

    for (const auto& testResult : manager.m_testResults) {
        rapidjson::Value testResultObject;
        testResultObject.AddMember("name", testResult.name.c_str(), testResult.name.size(), rapidjson::StringRef::AllocatorType());
        testResultObject.AddMember("duration", static_cast<double>(testResult.duration.count()), rapidjson::Value::NullType());
        testResultObject.AddMember("outcome", TestOutcomeStrings[static_cast<int>(testResult.outcome)].c_str(), TestOutcomeStrings[static_cast<int>(testResult.outcome)].size(), rapidjson::StringRef::AllocatorType());
        result["testResults"].PushBack(testResultObject, result.GetAllocator());
    }

    rapidjson::Value aggregateSummary;
    aggregateSummary.AddMember("totalTests", static_cast<double>(manager.m_testResults.size()), rapidjson::Value::NullType());
    aggregateSummary.AddMember("passedTests", static_cast<double>(countPassedTests(manager.m_testResults)), rapidjson::Value::NullType());
    aggregateSummary.AddMember("failedTests", static_cast<double>(countFailedTests(manager.m_testResults)), rapidjson::Value::NullType());
    aggregateSummary.AddMember("retriedTests", static_cast<double>(countRetriedTests(manager.m_testResults)), rapidjson::Value::NullType());
    for (const auto& errorType : ERROR_TYPES) {
        aggregateSummary.AddMember(errorType, static_cast<double>(countErrorOfType(manager.m_testResults, errorType)), rapidjson::Value::NullType());
    }
    result.AddMember("aggregateSummary", aggregateSummary, rapidjson::Value::NullType());

    return std::future<rapidjson::Document>{std::move(result)};
}

// Utilities for counting test outcomes.
int countPassedTests(const std::vector<TestResult>& testResults) {
    int passed = 0;
    for (const auto& testResult : testResults) {
        if (testResult.outcome == TestOutcome::Passed) {
            ++passed;
        }
    }
    return passed;
}

int countFailedTests(const std::vector<TestResult>& testResults) {
    int failed = 0;
    for (const auto& testResult : testResults) {
        if (testResult.outcome != TestOutcome::Passed) {
            ++failed;
        }
    }
    return failed;
}

int countRetriedTests(const std::vector<TestResult>& testResults) {
    int retried = 0;
    for (const auto& testResult : testResults) {
        if (testResult.outcome == TestOutcome::Retried) {
            ++retried;
        }
    }
    return retried;
}

int countErrorOfType(const std::vector<TestResult>& testResults, const std::string& errorType) {
    int count = 0;
    for (const auto& testResult : testResults) {
        if (testResult.outcome == TestOutcome::Error && testResult.name == errorType) {
            ++count;
        }
    }
    return count;
}
```

