```rust
use tokio::runtime;
use std::sync::{Arc, Mutex};
use std::collections::HashMap;

type Task = Box<dyn FnOnce() + Send + Sync>;

struct BackgroundTasks {
    tasks: Arc<Mutex<HashMap<u32, Task>>>,
    runtime: runtime::Runtime
}

impl BackgroundTasks {
    fn new(runtime: runtime::Runtime) -> Self {
        BackgroundTasks {
            tasks: Arc::new(Mutex::new(HashMap::new())),
            runtime,
        }
    }

    async fn add_task(&self, id: u32, task: Task) {
        let mut tasks = self.tasks.lock().await;
        tasks.insert(id, task);
        self.runtime.spawn(async move {
            match self.runtime.block_on(task).await {
                Ok(_) => println!("Task {} completed", id),
                Err(e) => println!("Error in task {}: {}", id, e),
            }
        });
    }
}
```

