class RateLimiter:
    def __init__(self, max_calls=60, reset_after=60):
        self.reset_time = time.time() + reset_after
        self.call_count = 0
        self.max_calls = max_calls

    def rate_limit(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if (time.time() - app.config['RATE_LIMIT_RESET']) < app.config['RATE_LIMIT_INTERVAL']:
                return func(*args, **kwargs), False
            app.config['RATE_LIMIT_RESET'] = time.time() + app.config['RATE_LIMIT_INTERVAL']
            result = func(*args, **kwargs)
            app.config['CALL_COUNT'] += 1
            if app.config['CALL_COUNT'] >= app.config['MAX_CALLS']:
                return 'Rate limited', False
