#include <json-c/json.h>

typedef struct json_response {
    char *access_token;
    int expires_in;
    char *token_type;
    // Add refresh_token field if needed
} json_response;

// Parse OAuth2 response JSON
void parse_oauth2_response(json_object *obj, json_response *response) {
    const char *access_token = json_object_get_string(obj, "access_token");
    if (!access_token) {
        log_error("Malformed JSON: Missing 'access_token' field.");
        return;
    }
    response->access_token = strdup(access_token);

    int expires_in = json_object_get_int(obj, "expires_in");
    if (expires_in <= 0) {
        log_error("Malformed JSON: Invalid 'expires_in' field.");
        return;
    }
    response->expires_in = expires_in;

    const char *token_type = json_object_get_string(obj, "token_type");
    if (!token_type) {
        log_error("Malformed JSON: Missing 'token_type' field.");
        return;
    }
    response->token_type = strdup(token_type);

    // Add refresh_token validation here if needed
}
