```csharp
using System.Collections.Concurrent;

public class RateLimiter
{
    private readonly ConcurrentDictionary<string, int> _counts = new ConcurrentDictionary<string, int>();
    public void Increment(string key) => _counts.AddOrUpdate(key, 1, (_, v) => v + 1);

    public bool IsLimited(string key, int maxRequestsPerInterval)
    {
        if (_counts.TryRemove(key, out var requests))
        {
            if (requests < maxRequestsPerInterval) return false;
            _counts[key] = 0;
