9. Implement retry logic using backoff strategies like exponential or jittered retries:

```rust
use futures::stream::StreamExt;
// ...
let mut retry_stream = directories_stream.iter().flat_map(|directory| {
    let directory = directory.clone();
    let retry_attempts = config.retry_attempts;
    let backoff_factor = config.backoff_factor;
    let backoff_jitter = config.backoff_jitter;

    let mut stream = futures::stream::iter(vec![directory]).into_stream();
    stream.flat_map(move |attempt| {
        let attempt = attempt;
        let retry_stream = stream.clone();
        async move {
            match directory.operation().await {
                Ok(_) => return futures::stream::iter(vec![]).into_stream(),
                Err(e) if e.is_transient() => {
                    info!("Retry attempt {} for operation on temp dir {}", attempt + 1, unique_name);
                    if attempt >= retry_attempts - 1 {
                        error!("Maximum retry attempts exceeded for operation on temp dir {}", unique_name);
                        return futures::stream::iter(vec![]).into_stream();
                    }

                    let backoff = (attempt as u64 + backoff_jitter) * backoff_factor;
                    tokio::time::sleep(Duration::from_secs(backoff)).await;
                    retry_stream
                }
                Err(_) => {
                    error!("Permanent failure for operation on temp dir {}", unique_name);
                    return futures::stream::iter(vec![]).into_stream();
                }
            }
        }
    })
});
```

