// Initialize semaphore with given initial value (N)
int N = /* your desired initial value */;
sem_init(&semaphore, 0, N);
pthread_mutex_init(&lock, NULL);

// Define error handling functions for resource exhaustion and communication issues
void handleError(const char *msg) {
    printf("%s\n", msg);
}

// Define a function to acquire the semaphore
void acquireSemaphore() {
    sem_wait(&semaphore);
    pthread_mutex_lock(&lock);
}

// Define a function to release the semaphore
void releaseSemaphore() {
    pthread_mutex_unlock(&lock);
    sem_post(&semaphore);
}

// Define your mission-critical function that requires synchronization using the semaphore
void criticalFunction(int id) {
    acquireSemaphore();

