#include <poco/Net/HTTPClientSession.h>
#include <poco/Net/HTTPRequest.h>
#include <poco/Net/HTTPResponse.h>

namespace {
    constexpr int kMaxRetries = 5;
    constexpr std::chrono::milliseconds kBaseBackoffTime = std::chrono::seconds(1);

    class AuthenticationManager {
    public:
        virtual bool authenticate(const std::string& apiKey) = 0;
        virtual std::shared_ptr<std::string> refreshToken() = 0;
        virtual ~AuthenticationManager() {}
    };

    class ResponseHandler {
    public:
        virtual void processResponse(const nlohmann::json& response) const = 0;
    };

    class JSONParser : public ResponseHandler {
    public:
        void processResponse(const nlohmann::json& response) const override {
            // Parse and process the JSON response here
        }
    };
}

class NetworkRequestHandler {
private:
    std::shared_ptr<AuthenticationManager> authenticationManager_;
    std::mutex requestsMutex_;
    std::condition_variable requestsCV_;
    int pendingRequestsCount_{0};
    boost::asio::io_service ioService_;
    boost::asio::strand strand_;

public:
    explicit NetworkRequestHandler(std::shared_ptr<AuthenticationManager> authenticationManager)
        : authenticationManager_(authenticationManager) {}

    void submitRequestWithRetry(const std::string& url, int retryCount,
                                 const std::shared_ptr<ResponseHandler>& responseHandler,
                                 const std::shared_ptr<Poco::Net::HTTPClientSession>& httpSession) {
        auto request = std::make_shared<boost::asio::ip::tcp::iostream>(url);

        if (!request->is_open()) {
            // Handle error and log message here
            return;
        }

        std::lock_guard<std::mutex> lock(requestsMutex_);
        ++pendingRequestsCount_;

        auto self = shared_from_this();
        auto task = [self, url, retryCount, responseHandler, httpSession]() {
            if (!self->authenticateRequest(*httpSession)) {
                // Log error and decrease pending requests count here
                return;
            }

            // Submit the request asynchronously using the strand to ensure thread safety
            self->strand_.async_write(*request, *httpSession->newRequest(url),
                                      [self](const boost::system::error_code& error) {
                                          if (!error) {
                                              // Handle response here and call processResponse on ResponseHandler
                                              self->handleResponse(*responseHandler, *request);
                                          } else {
                                              // Handle network errors and log message here
                                              --self->pendingRequestsCount_;
                                          }
                                      });
        };

        if (retryCount == 0) {
            task();
        } else {
            std::unique_lock<std::mutex> lock(requestsMutex_);
            requestsCV_.wait_for(lock, kBaseBackoffTime * std::pow(2, retryCount - 1),
                                [this]() { return pendingRequestsCount_ < kMaxRetries; });

            if (pendingRequestsCount_ >= kMaxRetries) {
                // Log error and decrease pending requests count here
                return;
            }

            task();
        }
    }

private:
    bool authenticateRequest(Poco::Net::HTTPClientSession& httpSession) const {
        // Implement authentication logic here, such as validating API key and refreshing token if necessary
    }

    void handleResponse(const ResponseHandler& responseHandler, boost::asio::ip::tcp::iostream& request) {
        nlohmann::json responseJson;
        try {
            responseJson = nlohmann::json::parse(request.get());
        } catch (const nlohmann::json::parse_error&) {
            // Handle invalid JSON responses and log message here
            return;
        }

        responseHandler.processResponse(responseJson);

        request.close();
        std::lock_guard<std::mutex> lock(requestsMutex_);
        --pendingRequestsCount_;
    }
};
```

