["Here is an outline for a modular JavaScript module called `ecom-footer-script-loader`. The code below assumes you have a basic understanding of AngularJS, ES6 syntax, Promises, and knowledge about caching, exponential backoff, and lazy loading strategies.

```javascript
// ecom-footer-script-loader.js
import { inject, Service } from 'angular';

@Service({
  name: 'ecomFooterScriptLoader'
})
export class EcomFooterScriptLoader {
  constructor(private $http, private $q, private configService) {}

  load() {
    const scriptConfig = this.configService.get('footer_scripts');

    return this.$q.all(scriptConfig.map((script) => {
      // Exponential backoff strategy with jitter (optional)
      // Implement using the `$timeout` service

      return this._loadScript(script);
    }));
  }

  _loadScript(script) {
    const deferred = this.$q.defer();

    if (!this._isValidScriptConfig(script)) {
      // Handle invalid input and log disallowed content attempts
      console.error(`Disallowed content attempt: ${script.src}`);
      return deferred.reject('Invalid script configuration');
    }

    this.$http.get(script.src)
      .then((response) => {
        // Cache response and parse JSON data (optional)
        // Implement using a cache library like ngCache or localStorage
        // Use AngularJS `$parse` to create a new function from the script body

        deferred.resolve(script);
      }, (error) => {
        // Retry failed external API calls with exponential backoff and manage concurrent updates
        if (!deferred.promise.isRejected()) {
          this.$timeout(() => this._loadScript(script), Math.random() * 2 ** script.attempts);
        } else {
          console.error(`Failed to load script: ${script.src}`, error);
        }
      });

    return deferred.promise;
  }

  _isValidScriptConfig(script) {
    // Validate each script object's uniqueness and sanitize the src attribute
    const allowedDomains = ['example1.com', 'example2.com']; // Customizable whitelist of allowed domains and origins

    if (!script || !script.src || !allowedDomains.includes(new URL(script.src).origin)) {
      return false;
    }

    return true;
  }
}
