2. Caching Module:

```javascript
const redis = require('redis'); // Use Redis for caching
const client = redis.createClient();

exports.storeAccessToken = (accessToken) => {
  client.setex(accessToken, 3600, JSON.stringify({ access_token: accessToken })); // Set expiration to 1 hour
};

exports.getAccessToken = (accessToken) => {
  return new Promise((resolve, reject) => {
    client.get(accessToken, (err, reply) => {
      if (err) return reject(err);
      try {
        const data = JSON.parse(reply);
        resolve(data.access_token);
      } catch (e) {
        // If the cached data is invalid or expired, remove it and resolve null
        client.del(accessToken, () => resolve(null));
      }
    });
  });
};
```

