```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

public class EncryptionService
{
    private readonly IKeyManagementSystem _kms;
    private readonly ILogger<EncryptionService> _logger;
    private readonly ExternalLoggingApi _loggingApi;

    public EncryptionService(IKeyManagementSystem kms, ILogger<EncryptDecryptService> logger, ExternalLoggingApi loggingApi)
    {
        _kms = kms;
        _logger = logger;
        _loggingApi = loggingApi;
    }

    public async Task<byte[]> EncryptAsync(byte[] data, string keyId)
    {
        var key = await _kms.GetKeyAsync(keyId);
        var iv = GenerateSecureIV();

        using (var aes = AES.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            using (var encryptor = aes.CreateEncryptor())
            {
                var encryptedData = EncryptData(data, encryptor);
                await _loggingApi.LogEncryptedDataAsync(keyId, data, encryptedData);
                return iv.Concat(encryptedData).ToArray();
            }
        }
    }

    public async Task<byte[]> DecryptAsync(byte[] data, string keyId)
    {
        var (iv, encryptedData) = SplitArrayIntoTwoParts(data);
        var key = await _kms.GetKeyAsync(keyId);

        using (var aes = AES.Create())
        {
            aes.Key = key;
            aes.IV = iv;
            using (var decryptor = aes.CreateDecryptor())
            {
                return DecryptData(encryptedData, decryptor);
            }
        }
    }

    private byte[] GenerateSecureIV()
    {
        // Implement efficient and secure IV generation strategy
    }

    private byte[] EncryptData(byte[] data, ICryptoTransform encryptor)
    {
        using (var ms = new MemoryStream())
        {
            using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
            {
                cs.Write(data);
            }
            return ms.ToArray();
        }
    }

    private byte[] DecryptData(byte[] data, ICryptoTransform decryptor)
    {
        using (var ms = new MemoryStream(data))
        {
            using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
            {
                var result = new byte[cs.ReadByte()];
                Array.Copy(cs.ReadAllBytes(), result, result.Length);
                return result;
            }
        }
    }

    private (byte[], byte[]) SplitArrayIntoTwoParts(byte[] array)
    {
        if (array.Length % 2 == 0)
        {
            throw new ArgumentException("IV size should always be less than data size.");
        }

        var iv = new byte[AES.KeySize / 8];
        Buffer.BlockCopy(array, 0, iv, 0, iv.Length);
        return (iv, array.Skip(iv.Length).ToArray());
    }
}
```

This example provides a simple encrypt and decrypt service that uses AES with a key management system for secure storage of keys. The service logs encrypted data to an external logging API and generates IVs using a placeholder method. This code does not include unit tests, integration tests, or error handling beyond validation checks in the `SplitArrayIntoTwoParts` method. These additions would be essential for ensuring the robustness and security of your implementation.

To improve scalability and performance, you should consider implementing caching strategies for frequently used keys or IVs, use asynchronous operations to handle concurrent requests efficiently, and carefully select an appropriate key management system based on your specific use case requirements. Furthermore, consider the impact of key rotation policies on system reliability and performance when deploying the service.']

