        Some(v) => Version::parse(v).expect("Invalid version number"),
        None => Version::new(1, 0, 0),
    };

    let supported_apis: Vec<&str> = env::args().skip(3).collect();

    let config_dir = Path::new(&dir_name);
    let config_path = config_dir.join(format!("config_{}", initial_version));

    match (fs::metadata(config_dir), fs::metadata(config_path)) {
        (Ok(_), Err(_)) => { // Create the directory and initialize the configuration file.
            init_config(&config_dir, &supported_apis);
        }
        (Err(_), Ok(_)) => { // Validate the existing configuration file and increment version if valid.
            validate_and_update_config(&config_dir, &supported_apis)
                .expect("Invalid configuration file found.");
        }
        (Err(e), Err(e)) => { // Handle errors when directories don't exist.
            eprintln!("Error creating directory or config file: {}", e);
        }
    }
}

fn init_config(dir: &Path, supported_apis: &[&str]) {
