fn validate_and_update_config(dir: &Path, supported_apis: &[&str]) -> Result<(), String> {
    let mut config = load_config(&config_path)?;

    if !validate_api_configs(&config, supported_apis) {
        return Err("Invalid API configurations.".to_string());
    }

    if Version::parse(config.version).unwrap() != initial_version {
        config.version += One;
    }

    save_config(&config, &config_path)?;
    set_env_var(CONFIG_PATH.to_str().unwrap(), config_path.to_str().unwrap());

    Ok(())
}

fn load_config(path: &Path) -> Result<Config, String> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    serde_json::from_reader(reader).map_err(|e| e.to_string())
}

fn save_config(config: &Config, path: &Path) -> Result<(), String> {
