```javascript
const express = require('express');
const axios = require('axios');
const bluebird = require('bluebird');
const fs = require('fs');
const path = require('path');
const _ = require('lodash');
const asyncLimit = require('async-limit');
const app = express();

// Configuration
const MAX_CONCURRENCY = process.env.MAX_CONCURRENCY || 10;
const API_URL = 'https://api.example.com'; // Replace with your API URL

// Middleware for handling file operations asynchronously
asyncLimit(MAX_CONCURRENCY)(async (req, res, next) => {
    const directoryPath = req.params.directory;
    const files = await bluebird.promisify(fs.readdir)(directoryPath);

    let processedFiles = 0;
    const promises = [];

    for (const file of files) {
        // Ensure the file exists and is a valid format
        if (!fs.existsSync(`${directoryPath}/${file}`)) continue;
        const stats = fs.statSync(`${directoryPath}/${file}`);
        if (stats.isDirectory()) continue;

        promises.push(processFile(file, directoryPath));
    }

    while (promises.length > 0) {
        try {
            const result = await bluebird.race(promises);
            processedFiles++;
            promises = promises.filter(promise => promise !== result);
        } catch (err) {
            console.error(`Error processing file: ${err}`);
        }
    }

    res.send(`Processed ${processedFiles} files`);
});

async function processFile(file, directoryPath) {
    const filePath = `${directoryPath}/${file}`;
    try {
        const contents = await bluebird.promisify(fs.readFile)(filePath);
        // Fetch metadata from API (using axios) and process the content here
        // Generate the report and handle errors gracefully
        // If there's an error, log detailed information for troubleshooting
    } catch (err) {
        console.error(`Error processing file ${file}: ${err}`);
    }
}

app.listen(3000, () => console.log('Server listening on port 3000'));
