typedef struct TaskQueueNode {
    void (*func)(void* arg);
    void* arg;
    struct TaskQueueNode* next;
} TaskQueueNode;

// Function prototypes
void init(const char* config_file, const char* db_url, const char* queue_url);
void cleanup();
bool populate(Record* record, int min, int max);
TaskQueueNode* enqueue(void(*func)(void*), void* arg);
