Here is the C function for generating a new state list in a given finite state automaton (FSA):

```c
#include <stdio.h>
#include <stdlib.h>

struct state {
    int id;
    struct state *next;
};

void init_state(struct state **head, int num_states, struct FSA *fsa, int last_state) {
    struct state* current = (struct state*)malloc(num_states * sizeof(struct state));
    if (!current) return NULL;

    for (int i = 0; i < num_states; ++i) {
        current[i].id = i;
        current[i].next = fsa->state_table[i];
    }

    // Update the last state's next pointer to point to the newly created list
    struct state *last_state_ptr = &current[last_state];
    while (last_state_ptr->next) {
        last_state_ptr = last_state_ptr->next;
    }
    last_state_ptr->next = current;

    *head = current;
}
```"]

