3. C Function for generating `NFAPI_CRC_INDICATION_PDU_T` structures (crc_generator.c)

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned char RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generateCRCPDU(NFAPI_CRC_INDICATION_PDU_T* pdu, int rnti) {
    time_t t = time(NULL);
    struct tm *now = localtime(&t);

    pdu->RX_UE_INFORMATION_TAG = now->tm_hour * 100 + now->tm_min;
    pdu->RNTI = (unsigned char) rnti;
    pdu->CRC_INDICATION_REL8_TAG = (int) rand();
    pdu->CRCFLAG = rand() % 2;
}
```

