bool token_validate(const char* json) {
    // Parse JSON using json-c library
    json_object *obj = json_tokener_parse(json);
    if (!obj || !json_object_get_exact(obj, "access_token")) return false;

    const char* access_token = json_object_get_string(json_object_get_exact(obj, "access_token"));
    if (!access_token) return false;

    // Ensure token_type is 'Bearer' and expires_in is a positive integer
    const char* token_type = json_object_get_string_exact(json_object_get_exact(obj, "token_type"));
    int expires_in;
    if (strcmp(token_type, "Bearer") != 0 || sscanf(json_object_get_string_exact(json_object_get_exact(obj, "expires_in"), "%d", &expires_in) != 1 || expires_in <= 0) {
        return false;
    }

    // Optional: Check for refresh_token if present
    const char* refresh_token = json_object_get_string(json_object_get_object_member(obj, "refresh_token"));
    if (refresh_token && strcmp(refresh_token, "") != 0) {
        // Implement validation of refresh_token here
    }

    json_object_put(obj); // Free the memory allocated by json-c library
    return true;
}
