["1. Union-Find Data Structure Implementation (Java)

```java
import java.util.DisjointSet;
import java.util.ArrayList;
import java.util.List;

public class DisjointSetUnionFind {
    private final List<Integer> parent;
    private final int[] size;

    public DisjointSetUnionFind(int numberOfNodes) {
        this.parent = new ArrayList<>(numberOfNodes);
        this.size = new int[numberOfNodes];

        for (int i = 0; i < numberOfNodes; i++) {
            parent.add(i);
            size[i] = 1;
        }
    }

    public int findSet(int node) {
        if (node != parent.get(node)) {
            parent.set(node, findSet(parent.get(node)));
        }
        return parent.get(node);
    }

    public void unionSets(int node1, int node2) {
        int root1 = findSet(node1);
        int root2 = findSet(node2);

        if (root1 != root2) {
            if (size[root1] < size[root2]) {
                parent.set(root1, root2);
                size[root2] += size[root1];
            } else {
                parent.set(root2, root1);
                size[root1] += size[root2];
            }
        }
    }
}
```

2. Transaction ID Pair Checker (Java)

```java
import java.util.Random;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class TransactionIDChecker {
    private static final int MAX_TRANSACTION_ID = 1000000000000L;
    private final DisjointSetUnionFind disjointSet;
    private final ConcurrentHashMap<Long, Long> transactionMap;
    private final ScheduledExecutorService scheduler;

    public TransactionIDChecker() {
        disjointSet = new DisjointSetUnionFind(MAX_TRANSACTION_ID * 2);
        transactionMap = new ConcurrentHashMap<>();
        scheduler = Executors.newScheduledThreadPool(1);
        scheduler.scheduleAtFixedRate(() -> transactionMap.forEach((id, _) -> disjointSet.unionSets(id, id + 1)), 0, 1, TimeUnit.MINUTES);
    }

    public boolean isDisjointPair(Long transactionID1, Long transactionID2) {
        return disjointSet.findSet(transactionID1) != disjointSet.findSet(transactionID2);
    }

    public void registerTransaction(Long transactionID, Object metadata) {
        if (transactionMap.putIfAbsent(transactionID, metadata) == null) {
            disjointSet.unionSets(transactionID, transactionID + 1);
        }
    }
}
```

