['1. Securely deleting a file and executing an external command in Java:

```java
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import javax.script.ProcessBuilder;
import javax.script.ScriptEngineManager;
import javax.script.ScriptException;

public class FileAndCommandOperations {
    public void deleteFileIfExists(String filePath) throws IOException {
        File file = new File(filePath);
        if (file.exists()) {
            Files.delete(file.toPath());
        }
    }

    public String executeExternalCommand(List<String> command) throws ScriptException, IOException {
        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true);
        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        StringBuilder output = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }

        process.waitFor();
        return output.toString();
    }
}
```

