2. **Worker Pool**

```javascript
const cluster = require('cluster');

function createWorkerPool(concurrencyLimit) {
  if (cluster.isMaster) {
    // Fork workers and manage them in the worker pool.
    for (let i = 0; i < concurrencyLimit; i++) {
      cluster.fork();
    }

    return {
      enqueue: (task) => {
        cluster.workers.forEach((worker) => worker.send({ type: 'task', data: task }));
      },
    };
  } else {
    // Worker processes should handle log processing tasks as they receive them.
  }
}
```

