fn process_images(
    image_paths: Vec<String>,
    filter_set: FilterType,
    cache: Cache,
    metadata_extractor: &MetadataExtractor,
) -> (Vec<ImageOps>, Vec<ImageMetadata>) {
    let mut img_ops = Vec::with_capacity(image_paths.len());
    let mut meta_data = Vec::with_capacity(image_paths.len());

    image_paths.par_iter().enumerate()
        .map(|(i, path)| {
            let file = if is_local_url(&path) {
                BufReader::new(File::open(Path::new(&path)).unwrap())
            } else {
                TokioFile::open(Url::parse(&path).unwrap()).await.unwrap()
