#[tokio::main]
async fn main() {
    let runtime = Runtime::new().expect("Failed to create Tokio runtime");

    // Define your tasks here. Each task should be a Stream or Future returned by an asynchronous function.

    let mut handles = vec![];

    for task in tasks() {
        let handle = runtime.spawn(task);
        handles.push(handle);
    }

    // Run all the tasks concurrently and collect their futures.
    // The `join_all` function will wait for all the tasks to complete.
    if let Ok(()) = runtime.block_on(handles.into_iter().collect::<Vec<_>>()).await {
