        if (!transaction) break;

        // Authenticate the incoming request, derive keys, and set up AES-GCM context
        jwt_authenticate(transaction->header);
        uint8_t iv[16];
        uint8_t key[32];
        derive_key(key, transaction->header->kid);

        aes_gcm_context_t ctx;
        aes_gcm_init(&ctx, key, iv);

        // Decrypt and process the payload, handle errors gracefully
        char *payload = decrypt_data(transaction->payload, transaction->length);
        if (!payload) {
