    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 100000
static NFAPI_CRC_INDICATION_PDU_T* data_pool = NULL;
static size_t num_elements = 0;
static const size_t pool_size = (MAX_ELEMENTS + sizeof(NFAPI_CRC_INDICATION_PDU_T) - 1) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
static pthread_mutex_t data_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

void get_external_data(RNTI* rnti_mapping, size_t num_requests, size_t* processed) {
    // Implement the logic to retrieve external data from a data source.
}

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_data(size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Requested number of elements exceeds the maximum allowed.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_lock(&data_pool_mutex);
    size_t remaining = pool_size - num_elements;
    if (remaining > 0) {
        num_elements += pool_size;
        data_pool += remaining;
    }
    pthread_mutex_unlock(&data_pool_mutex);

    RNTI* rnti_mapping = malloc(num_elements * sizeof(RNTI));
    if (!rnti_mapping) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(data);
        return NULL;
    }

    size_t processed = 0;
    while (processed < num_elements) {
        get_external_data(rnti_mapping + processed, num_elements - processed, &processed);
        if (processed >= num_elements) break;
    }

    if (processed != num_elements) {
        fprintf(stderr, "Error: Failed to retrieve external data for all elements.\n");
        free(rnti_mapping);
        free(data);
        return NULL;
    }

    for (size_t i = 0; i < num_elements; ++i) {
        data[i].tag = GENERATE_TAG(); // Replace GENERATE_TAG() with the logic to generate a valid RX_UE_INFORMATION_TAG.
        data[i].rnti = rnti_mapping[i];
        data[i].crc_indication = GENERATE_CRC_INDICATION(); // Replace GENERATE_CRC_INDICATION() with the logic to generate a valid CRC_INDICATION_REL8_TAG.
        data[i].crcflag = rand() % 2;
    }

    free(rnti_mapping);
    return data;
}

void cleanup() {
    if (data_pool) {
        free(data_pool);
        data_pool = NULL;
        num_elements = 0;
    }
}
```

