        $this->hashAlgorithm = $hashAlgorithm;
        $this->dbConnection = $dbConnection;
        $this->cache = new \Predis\Client(); // Assuming you use Predis for PHP Redis
    }

    public function generateRandomString($length, $charset) {
        $key = "random_string_{$length}_{$charset}";
        if (!isset($this->cache[$key])) {
            $response = $this->makeApiCall($length, $charset);
            $randomString = $response['result'];
            $this->cache->set($key, $randomString, 600); // Cache for 10 minutes
        } else {
            $randomString = $this->cache[$key];
        }
        return $randomString;
    }

    private function makeApiCall($length, $charset) {
        $url = "{$this->apiUrl}/generate/{$length}/{$charset}";
        $headers = ['Authorization: Bearer ' . $this->apiKey];

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $url);
        curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

        $response = json_decode(curl_exec($ch), true);
        $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

        if ($httpCode != 200) {
            $this->logError("API request failed with status code {$httpCode}", $response);
            sleep(pow(2, rand(0, 3))); // Exponential backoff
            return $this->makeApiCall($length, $charset);
        }

        return $response;
    }

    public function hashPassword($password) {
        $hasher = new \Passlib\Hash\Argon2idHash();
        return $hasher->hash($password);
    }

    private function storePassword($userId, $passwordHash) {
        // Assuming you use PDO for database interactions
        $query = "UPDATE users SET password = ? WHERE id = ?";
        $stmt = $this->dbConnection->prepare($query);
        $stmt->execute([$passwordHash, $userId]);
    }

    private function logError($message, $context = []) {
        // Assuming you use a logging library like Monolog for PHP
        $logger = new \Monolog\Logger("app");
        $logger->error($message, $context);
    }
}
```

