NFAPI_CRC_INDICATION_PDU_T* generateNFAPDUList(int N, const char *input) {
    // Validate input and append a / if its length does not exceed maxSize
    size_t len = strlen(input);
    sem_wait(&config_mutex);
    if (len > MAX_SIZE) {
        sem_post(&config_mutex);
        return NULL;
    }
    char *appendedInput = malloc(len + 1); // +1 for the appended /
    strcpy(appendedInput, input);
    appendedInput[len] = '/';
    sem_post(&config_mutex);

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures and populate them with randomly set CRCFLAG values.
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = rand();
        pdus[i].RNTI = rand();
        pdus[i].CRC_INDICATION_REL8_TAG = rand();
        pdus[i].CRCFLAG = rand() % 2 == 0; // 50% chance of setting CRCFLAG to true
    }

    // Optimized for speed and memory usage.
    return pdus;
}
