    virtual void alert(const std::string& msg) = 0;
    virtual void log_detail(const std::string& msg) = 0;
};

// Implementation of the forward list using boost::container::flat_map
using StringList = boost::container::flat_map<std::string, std::list<boost::container::string>>;

class ForwardList {
public:
    // Constructor taking configuration and logger
    explicit ForwardList(const Config& config, std::shared_ptr<ILogger> logger) : logger_(logger), threshold_(config.threshold) {}

    void insert(const std::string& target, const std::string& value);
    // Other supporting functions like get, clear, size etc.

private:
    std::shared_ptr<ILogger> logger_;
    int threshold_;
};

void ForwardList::insert(const std::string& target, const std::string& value) {
    auto it = string_list_.find(target);
    if (it != string_list_.end()) {
        it->second.push_front(value);
        if (it->second.size() > threshold_) {
            logger_->alert("List exceeded the configured threshold.");
            it->second.pop_back();
        }
    } else {
        string_list_[target].emplace_back(value);
    }
}
```

