```javascript
const axios = require('axios'); // External HTTP client for API requests
const Bluebird = require('bluebird'); // Promises for asynchronous operations
const _ = require('lodash'); // Utility functions for batching and optimization

class NetworkHealthChecker {
  constructor(config) {
    this.apiBaseUrl = config.apiBaseUrl;
    this.quotaLimit = config.quotaLimit;
    this.refreshRate = config.refreshRate;
    this.retryCountMax = config.retryCountMax;
    this.retryIntervalBaseMS = config.retryIntervalBaseMS;
  }

  async getNetworkHealth(callback) {
    try {
      const response = await axios.get(`${this.apiBaseUrl}/network-health`);
      callback(null, response.data);
    } catch (error) {
      this.handleError(error, callback);
    }
  }

  handleError(error, callback) {
    if (error.response && error.response.status === 429) { // Quota exceeded
      setTimeout(() => this.getNetworkHealth(callback), this.refreshRate);
    } else {
      const retryCount = error.config && error.config.retryCount || 0;
      if (retryCount < this.retryCountMax) {
        const backoffIntervalMS = Math.pow(2, retryCount) * this.retryIntervalBaseMS;
        setTimeout(() => this.getNetworkHealth(callback), backoffIntervalMS);
      } else {
        callback(error);
      }
    }
  }
}

class PduManager {
  constructor() {
    this.pdus = [];
    this.healthChecker = new NetworkHealthChecker({ /* config */ });
    this.healthChecker.getNetworkHealth(() => this.refreshPdus());
  }

  refreshPdus() {
    Bluebird.map(_.chunk(this.pdus, 10), async (chunk) => { // Batching for performance
      try {
        const networkHealth = await this.healthChecker.getNetworkHealth();
        // Process the chunk using the latest network health information
        return processPduChunk(networkHealth, chunk);
      } catch (error) {
        console.error(`Error refreshing pdus: ${error}`);
        return [];
      }
    })
    .then((results) => this.pdus = [].concat(...results)) // Flatten the results array
    .catch((error) => console.error(`Error processing pdus: ${error}`));
  }
}

function processPduChunk(networkHealth, pduChunk) {
