namespace HttpService
{
    public interface INetworkRequestManager
    {
        Task<HttpResponseMessage> SendAsync(HttpRequestMessage request);
        event EventHandler<RequestPerformedEventArgs> RequestPerformed;
    }

    public class NetworkRequestManager : INetworkRequestManager
    {
        private readonly IServiceProvider _serviceProvider;
        private readonly RateLimiter _rateLimiter;
        private readonly ThreadPool _threadPool;
        private readonly Queue<HttpRequestMessage> _requestQueue;

        public event EventHandler<RequestPerformedEventArgs> RequestPerformed;

        public NetworkRequestManager(IServiceProvider serviceProvider, IRateLimiter rateLimiter, int maxDegreeOfParallelism)
        {
            _serviceProvider = serviceProvider;
            _rateLimiter = rateLimiter;
            _threadPool = new ThreadPool(maxDegreeOfParallelism);
            _requestQueue = new Queue<HttpRequestMessage>();
        }

        public async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request)
        {
            if (!_rateLimiter.AllowRequest()) return new HttpResponseMessage(System.Net.HttpStatusCode.TooManyRequests);

            _requestQueue.Enqueue(request);
            await _threadPool.AddTask(() => ProcessRequest(request));

            RequestPerformed?.Invoke(this, new RequestPerformedEventArgs { Request = request });
            return default; // Placeholder for the response to be filled in by ProcessRequest
        }

        private void ProcessRequest(HttpRequestMessage request)
        {
            var service = _serviceProvider.GetService<IExternalService>();
            using (var client = new HttpClient())
            {
                // Customize API version, authentication scheme, and endpoint configuration here using environment variables or configuration files
