<?php

class UserAccountManager {
    private $db;
    private $authService;
    private $cache;
    private $rateLimiter;

    public function __construct(PDO $db, ExternalAuthService $authService, Cache $cache, RateLimiter $rateLimiter) {
        $this->db = $db;
        $this->authService = $authService;
        $this->cache = $cache;
        $this->rateLimiter = $rateLimiter;
    }

    public function handleRequest($data, $subAction) {
        if (!$this->validate($data)) {
            return ['status' => 'error', 'message' => 'Invalid input data'];
        }

        $this->rateLimiter->check();

        switch ($subAction) {
            case 'create':
                return $this->createUserAccount($data);
            case 'update':
                return $this->updateUserAccount($data);
            case 'delete':
                return $this->deleteUserAccount($data);
        }
    }

    private function validate($data) {
        if (!isset($data['email']) || !filter_var($data['email'], FILTER_VALIDATE_EMAIL)) {
            return false;
        }

        $cachedEmails = $this->cache->get('emails');
