3. Implement the C function in the provided `c-dependency` example:

```c
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

char* append_slash(const char *str, size_t size_limit) {
    if (strlen(str) > size_limit || size_limit <= 0) {
        return NULL;
    }

    size_t str_len = strlen(str);
    char *result = malloc(str_len + 2);
    if (!result) {
        return NULL;
    }

    memcpy(result, str, str_len);
    result[str_len] = '/';
    result[str_len + 1] = '\0';

    return result;
}
```

4. Create a Rust FFI wrapper for the C function:

```rust
extern crate libc;
use libc::{c_char, c_uint};

use std::ffi::{CString, CStr};
use std::os::raw::c_char::{self, CString};
use std::ptr::null;

#[no_mangle]
pub extern "C" fn append_slash(str: *const c_char, size_limit: c_uint) -> *mut c_char {
    let input = unsafe { CStr::from_ptr(str as *const i8) };
    let size_limit = size_limit as usize;
    match input.to_str().and_then(|s| s.len().checked_sub(size_limit)) {
        Some(remaining) if remaining > 0 => null(),
        _ => unsafe { CString::new(format!("{}{}", input.to_str().unwrap(), "/")).into_raw() },
    }
}
```

