['```csharp
#nullable enable
using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Newtonsoft.Json;

namespace DynamicRandomValueGenerator
{
    public interface IRandomValueGenerator
    {
        Task<double> GetNextAsync(int rangeIndex);
    }

    public sealed class RangeConfig
    {
        [JsonProperty("min")]
        public double Min { get; set; }

        [JsonProperty("max")]
        public double Max { get; set; }
    }

    public sealed class RangePartition
    {
        private readonly ConcurrentQueue<RangeConfig> _ranges;
        private readonly IRandomValueGenerator _generator;
        private readonly ILogger<RangePartition> _logger;

        public RangePartition(IRandomValueGenerator generator, ILogger<RangePartition> logger)
        {
            _generator = generator;
            _logger = logger;
            _ranges = new ConcurrentQueue<RangeConfig>();
        }

        public void AddRange(RangeConfig range) => _ranges.Enqueue(range);

        private async Task<double> GetNextAsync(int partitionIndex, CancellationToken cancellationToken = default)
        {
            while (!_ranges.IsEmpty)
            {
                var currentRange = _ranges.Dequeue();
                if (currentRange != null && !cancellationToken.IsCancellationRequested)
                {
                    return await _generator.GetNextAsync(PartitionRangeToIndex(partitionIndex, currentRange));
                }
            }

            throw new InvalidOperationException("No valid range found.");
        }

        private int PartitionRangeToIndex(int partitionIndex, RangeConfig currentRange) => (int)((currentRange.Max - currentRange.Min) * partitionIndex / PartitionsCount) + currentRange.Min;
    }

    public sealed class RandomValueGenerator : IRandomValueGenerator
    {
        private readonly ConcurrentDictionary<int, RangePartition> _partitions;
        private readonly ILogger<RandomValueGenerator> _logger;

        public RandomValueGenerator(ILogger<RandomValueGenerator> logger)
        {
            _partitions = new ConcurrentDictionary<int, RangePartition>();
            _logger = logger;
        }

        public void AddRange(params RangeConfig[] ranges) => AddRanges(ranges.AsParallel());

        public void AddRanges(ParallelQuery<RangeConfig> ranges)
        {
            var partitionsCount = (int)Math.Sqrt(ranges.Count() + 1);
            var partitionIndex = 0;
            foreach (var range in ranges)
            {
                _partitions.GetOrAdd(partitionIndex, x => new RangePartition(_generator, _logger))!.AddRange(range);
                if ((++partitionIndex >= partitionsCount))
                    partitionIndex = 0;
            }
        }

        private readonly SemaphoreSlim _semaphore = new SemaphoreSlim(1, 1);

        public async Task<double> GetNextAsync(CancellationToken cancellationToken = default)
        {
            await _semaphore.WaitAsync(cancellationToken);
            try
            {
                var task = Task.WhenAll(_partitions.Values.Select(x => x.GetNextAsync(PartitionIndex, cancellationToken)));
                var result = await Task.WhenAny(task);
                _semaphore.Release();
                return result;
            }
            catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
            {
                throw new InvalidOperationException("Task cancellation was unexpected.");
            }
        }

        private int PartitionIndex => Thread.CurrentThread.ManagedThreadId % _partitions.Count;
    }
}
```

This code provides a basic implementation of the `DynamicRandomValueGenerator`. The library is thread-safe, integrates an external logging service, and supports concurrent random value generation across multiple numeric ranges. The design allows for dynamic range management and error handling mechanisms, and it's optimized for performance with caching strategies and lock-free algorithms. To use the library, you can create a new instance of the `RandomValueGenerator`, add your range configurations, and call the `GetNextAsync` method to obtain a random value within the specified ranges.']

