    {
        var dataChunks = SplitData(file);

        foreach (var chunk in dataChunks)
        {
            await ProcessDataChunkAsync(chunk, clientId);
        }
    }

    private IEnumerable<byte[]> SplitData(IFormFile file)
    {
        var bufferSize = _configuration["DataTransfer:BufferSize"];
        var position = 0;

        while (position < file.Length)
        {
            yield return file.ReadBytes((int)Math.Min(bufferSize, file.Length - position));
            position += bufferSize;
        }
    }

