['1. C Header File (crc_indication_pdu.h)

```c
#ifndef CRCIMPDU_H
#define CRCIMPDU_H

#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crcind;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_NUM_ELEMENTS 10000

extern sem_t mutex, num_elements_semaphore;
extern pthread_cond_t elements_ready_condition;
extern NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdus;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(void);
bool add_crc_indication_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu);
void delete_all_pdus(void);

#endif // CRCIMPDU_H
```

2. C Source File (crc_indication_pdu.c)

```c
#include "crc_indication_pdu.h"
#include <stdlib.h>
#include <time.h>

static NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdus;
static sem_t mutex, num_elements_semaphore;
static pthread_cond_t elements_ready_condition;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(void) {
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) return NULL;

    sem_wait(&num_elements_semaphore);
    sem_gettaskname(sem_self(), 0, NULL, sizeof(char)*4096);
    char* taskName = sem_gettaskname(sem_self(), 0, NULL, sizeof(char)*4096);
    printf("Creating new CRC indication PDU by thread: %s\n", taskName);
    free(taskName);

    new_pdu->crcind.value = rand() & 0xFF;
    new_pdu->rnti = rand();
    new_pdu->tag.value = rand();
    new_pdu->crcflag = rand() % 2 == 0 ? true : false;

    sem_post(&mutex);
    pthread_cond_signal(&elements_ready_condition);
    return new_pdu;
}

bool add_crc_indication_pdu(const NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_wait(&mutex);
    if (sem_tryacquire(&num_elements_semaphore, 0)) {
        int index = (crc_indication_pdus - crc_indication_pdus + MAX_NUM_ELEMENTS) % MAX_NUM_ELEMENTS;
        memcpy(crc_indication_pdus + index, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        sem_post(&num_elements_semaphore);
        return true;
    }
    sem_post(&mutex);
    return false;
}

void delete_all_pdus(void) {
    if (!crc_indication_pdus) return;

    free(crc_indication_pdus);
    crc_indication_pdus = NULL;
}
```

3. JavaScript Function for Buffer Copying (buffer-copy.js)

```javascript
function copyBufferChunks(srcBuffers, dstBuffer, count) {
    const len = srcBuffers[0].length;
    const chunkSize = Math.ceil(len / count);

    let offset = 0;
    for (let i = 0; i < count; ++i) {
        const bufferChunk = Buffer.allocUnsafe(chunkSize);
        for (let j = 0; j < chunkSize && offset + j < len; ++j) {
            bufferChunk.writeUInt8(srcBuffers[0][offset + j], j);
        }
        dstBuffer.copy(bufferChunk, 0, offset, offset + chunkSize);
        offset += chunkSize;
    }
}
```']

