['Here's a basic implementation of the `FileExtensionModifier` class in C# that follows your requirements:

```csharp
using System;
using System.Collections.Concurrent;
using System.IO;
using System.Linq;
using System.Reflection;

public class FileExtensionModifier
{
    private readonly string _originalFileName;
    private readonly string _fileType;
    private readonly IConfigurationService _configurationService;
    private readonly Random _random = new Random();
    private readonly ConcurrentDictionary<string, (string OriginalFileName, string ModifiedFileName)> _cache = new ConcurrentDictionary<string, (string, string)>();

    public FileExtensionModifier(string originalFileName, IConfigurationService configurationService)
    {
        _originalFileName = originalFileName;
        _configurationService = configurationService;
    }

    public string GenerateNewFileName()
    {
        if (!_cache.TryGetValue(_originalFileName, out var (_, modifiedFileName)))
        {
            var fileType = GetFileType();
            var digitsToAppend = GetNumberOfDigitsToAppend();
            var newFileName = $"{_originalFileName.Split('.').Take(digitsToAppend + 1).Concat(_fileType).Join(".")}.{fileType}";

            _cache[newFileName] = (_originalFileName, newFileName);

            if (!_configurationService.IsCachingEnabled)
                ClearCache();
        }

        return _cache[_originalFileName].ModifiedFileName;
    }

    private string GetFileType()
    {
        var fileExtension = Path.GetExtension(_originalFileName).ToLowerInvariant();
        return _configurationService.GetSupportedFileTypes().Contains(fileExtension) ? fileExtension : _fileType;
    }

    private int GetNumberOfDigitsToAppend()
    {
        // Customize this method to fit your needs, e.g., using regular expressions for pattern matching.
        var digitsCount = 0;
        if (_originalFileName.Any(char.IsDigit))
            _originalFileName.Where(char.IsDigit).ToList().ForEach(_ => ++digitsCount);
        return _configurationService.GetNumberOfDigits() > 0 ? Math.Min(_configurationService.GetNumberOfDigits(), digitsCount) : digitsCount;
    }

    private void ClearCache()
    {
        if (Thread.CurrentThread.IsBackground && !_configurationService.IsCachingEnabled)
            _cache.Clear();
    }

    public override string ToString() => $"Original: {_originalFileName}, Modified: {GenerateNewFileName()}";
}

public interface IConfigurationService
{
    string GetFileType(string fileExtension = "");
    int GetNumberOfDigits(int defaultValue = 4);
    bool IsCachingEnabled { get; }
    IEnumerable<string> GetSupportedFileTypes();
}
```

This implementation uses a concurrent dictionary for caching, allowing safe and efficient filename lookups in a multi-threaded environment. It also handles edge cases where the cache is disabled by using a fallback mechanism to clear it when necessary.

The `IConfigurationService` interface abstracts away the details of the external configuration service, enabling you to use different implementations as needed. The default implementation here simply uses properties and a method to configure the behavior.']

