        self.process_notification(data)

class LoadBalancer:
    def __init__(self, regions):
        self.regions = regions
        self.last_accessed = [datetime.now() for _ in regions]

    def next_region(self):
        min_timestamp = float('inf')
        current_index = 0
        for index, timestamp in enumerate(self.last_accessed):
            if timestamp < min_timestamp:
                min_timestamp = timestamp
                current_index = index
        self.last_accessed[current_index] = datetime.now()
        return self.regions[current_index]
