    private final int maxIntValue;
    private final double minFloatValue;
    private final double maxFloatValue;
    private final Supplier<BigDecimal> seedSupplier;
    private final ConcurrentHashMap<Integer, Integer> unionFind;
    private final AtomicLong lastSeed;
    private boolean apiConnected = true;

    public DynamicValueGenerator(int minIntValue, int maxIntValue, double minFloatValue, double maxFloatValue, URL seedApiUrl) {
        this.minIntValue = minIntValue;
        this.maxIntValue = maxIntValue;
        this.minFloatValue = minFloatValue;
        this.maxFloatValue = maxFloatValue;

        this.seedSupplier = createSeedSupplier(seedApiUrl);
        this.unionFind = new ConcurrentHashMap<>();
        this.lastSeed = new AtomicLong();
    }

