    }

    public int generateRandomInt() {
        long currentTime = Instant.now().toEpochMilli();
        lastSeed.set(currentTime);

        Integer[] disjointSets = unionFindValues(new Integer[]{maxIntValue, minIntValue});
        if (disjointSets[0] == disjointSets[1]) {
            return generateRandomIntWithNewSet();
        } else {
            return disjointSets[Math.random() < 0.5 ? 0 : 1];
        }
    }

    public double generateRandomFloat() {
        long currentTime = Instant.now().toEpochMilli();
        lastSeed.set(currentTime);

        return Math.random() * (maxFloatValue - minFloatValue) + minFloatValue;
    }

    private Integer[] unionFindValues(Integer[] values) {
        // Implement Union-Find using the path compression optimization
    }

    private int generateRandomIntWithNewSet() {
        long seed = seedSupplier.get().longValue();
        lastSeed.set(seed);

        int value;
        do {
            value = (int) ((Math.abs(seed % (maxIntValue - minIntValue + 1)) + minIntValue));
        } while (unionFind.containsKey(value));

        unionFind.computeIfAbsent(value, k -> value);
        return value;
    }

    public void verifyApiConnection() {
