    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("DynamicValueGenerator [minIntValue=").append(minIntValue)
                .append(", maxIntValue=").append(maxIntValue)
                .append(", minFloatValue=").append(minFloatValue)
                .append(", maxFloatValue=").append(maxFloatValue)
                .append(", lastSeedUsed=").append(lastSeed.get())
                .append(", apiConnected=").append(apiConnected).append(']');
        return sb.toString();
    }
}
