class PaymentModule {
private:
    std::map<std::string, std::unique_ptr<PaymentGateway>> gateways;
    ml_model model;
    MonitoringAPI monitoring;

public:
    void addGateway(const std::string& name, std::unique_ptr<PaymentGateway> gateway) {
        gateways[name] = std::move(gateway);
    }

    bool processTransaction(const nlohmann::json& request) {
        // Use machine learning model to predict optimal payment gateway
        auto predictedGateways = model.predict(request);

        for (auto& [name, gateway] : gateways) {
            if (predictedGateways.count(name)) {
                // Try the selected gateway first
                if (gateway->authenticate() && gateway->sendRequest(request).empty()) {
                    gateway->onResponse(gateway->sendRequest(request));
                    return validateAndLogTransaction(request, gateway->onResponse(request));
                }
            }
        }

        // If all selected gateways fail, try remaining gateways in order of success rates and load
        for (auto& [name, gateway] : gateways) {
            if (!predictedGateways.count(name)) {
                if (gateway->authenticate() && gateway->sendRequest(request).empty()) {
                    gateway->onResponse(gateway->sendRequest(request));
                    return validateAndLogTransaction(request, gateway->onResponse(request));
                }
            }
        }

        LOG_ERROR("All gateways failed to process transaction");
        return false;
    }

private:
    bool validateAndLogTransaction(const nlohmann::json& request, const std::string& response) {
        nlohmann::json jsonResponse = nlohmann::json::parse(response);

        if (!validateTransaction(request, jsonResponse)) {
            LOG_ERROR("Invalid transaction: " + request.dump());
            return false;
        }

        // Log successful transactions and their details
        LOG_INFO("Transaction processed successfully: " + request.dump());
        monitoring.logSuccessfulTransaction();

        return true;
    }

    bool validateTransaction(const nlohmann::json& request, const nlohmann::json& response) {
        // Validate essential fields (transaction_id, amount, status, card_number)
        if (!validateField(request, "transaction_id", response["transaction_id"]) ||
            !validateField(request, "amount", response["amount"]) ||
            response.find("status") == response.end() ||
            !validateField(request, "card_number", response["card_number"])) {
            return false;
        }

        // Optionally validate additional payment-specific fields like cvv and expiry_date
        if (response.find("cvv") != response.end())
            // Implement validation logic here

        if (response.find("expiry_date") != response.end())
            // Implement validation logic here

