    let path = Path::new(&sanitized_dir);
    let mut parent_path = path.parent().cloned();
    let mut retries = 0;
    while parent_path.is_some() && retries < MAX_RETRIES {
        if !ALLOWED_PATHS.iter().any(|allowed| allowed.regex(parent_path.as_ref())) {
            log::error!("Attempted to create a directory outside the whitelist: {}", parent_path.display());
            break;
        }
        if let Some(depth) = parent_path.map(|p| p.components().count() - 1).and_then(|d| d.checked_sub(DEPTH_LIMIT)) {
            log::error!("Directory nesting exceeded the depth limit: {}", parent_path.display());
            break;
        }
        match create_dir_with_retry(&parent_path, &storage).await {
            Ok(_) => break,
            Err(e) => {
                retries += 1;
                log::error!("Failed to create directory. Retrying... {}", e);
                sleep(RETRY_DELAY_BASE * std::u64::from(retries)).await;
            }
        }
    }

    if let Some(parent_path) = parent_path {
