import { inject, Injectable } from '@angular/core';
@Injectable({
  providedIn: 'root'
})
export class DialogRefreshService {
  private config;
  private messageChannels = {};

  constructor() {
    this.config = inject(ConfigurationService);
  }

  refreshDialogFields(fieldNames, resourceId, url) {
    const windowRef = window as any;
    if (!windowRef.parent) return;

    const messageChannelKey = `${resourceId}:${url}`;
    if (this.messageChannels[messageChannelKey]) return;
    this.messageChannels[messageChannelKey] = true;

    const messageChannel = windowRef.parent.addEventListener('message', (event) => {
      if (event.data === 'refresh') {
        for (const fieldName of fieldNames) {
          const dialogField = document.querySelector(`[name="${fieldName}"]`);
          if (dialogField) dialogField.value = event.data[fieldName];
        }
      }
    });

    windowRef.parent.postMessage({ resourceId, url, fieldNames }, '*');
  }
}
