  2. External Logging Service Integration (C)

```c
#include "logging.h"
#include <stdlib.h>
#include <time.h>

bool log_service_is_available();
void log_to_external(Logger*, enum LogLevel, const char*, ...);

// Implement log_to_external function to communicate with the external logging service

Logger* logger_init(enum LogLevel level, LogFunction log_fn) {
    Logger* logger = malloc(sizeof(Logger));
    pthread_mutex_init(&logger->lock, NULL);
    logger->level = level;
    logger->log_fn = log_fn;
    logger->is_enabled = true;
    return logger;
}

void logger_set_log_function(Logger* logger, LogFunction log_fn) {
    logger->log_fn = log_fn;
}

void logger_enable(Logger* logger) {
    logger->is_enabled = true;
}

void logger_disable(Logger* logger) {
    logger->is_enabled = false;
}

void logger_log(Logger* logger, enum LogLevel level, const char* format, ...) {
    if (!logger->is_enabled || level > logger->level)
        return;

    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&logger->lock);

    if (log_service_is_available()) {
        log_to_external(logger, level, format, args);
    }

    // Implement rate limiting strategy here

    pthread_mutex_unlock(&logger->lock);
    va_end(args);
}
```

