['1. **C Program (pthread_semaphore implementation)**

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    pthread_t threads[100];
    pthread_sem_t semaphore;
    int max_threads;
} Semaphore;

void init_semaphore(Semaphore *sem, int max_threads) {
    sem->max_threads = max_threads;
    pthread_sem_init(&sem->semaphore, NULL, max_threads);
}

void* worker(void* data) {
    // Add your custom logic for each thread here.
    return NULL;
}

void run(Semaphore *sem, void (*worker)(void*)) {
    int i;
    for (i = 0; i < sem->max_threads; ++i) {
        pthread_create(&sem->threads[i], NULL, worker, NULL);
    }

    // Wait for all threads to finish.
    for (i = 0; i < sem->max_threads; ++i) {
        pthread_join(sem->threads[i], NULL);
    }
}
```

