    ```javascript
function copyBufferedData(buffers, numBytes) {
  const dest = Buffer.allocUnsafe(numBytes);
  let readIndex = 0;
  let totalRead = 0;

  for (const buffer of buffers) {
    const remaining = Math.min(buffer.length - readIndex, numBytes - totalRead);
    if (remaining > 0) {
      dest.set(buffer.slice(readIndex, readIndex + remaining), totalRead);
      totalRead += remaining;
      readIndex += remaining;
    }
  }

  return dest.slice(0, totalRead);
}
