2. File Conversion Function (C)
   ```c
   #include <stdio.h>
   #include <stdlib.h>
   #include <libjpg.h>
   #include <pdf-lib.h>

   void convertJpegToPdf(char* fileName) {
       // Load JPEG image
       struct jpeg_decompress_struct cinfo;
       struct jpeg_error_mgr jerr;
       FILE *infile = fopen(fileName, "rb");
       jpeg_create_decompress(&cinfo, &jerr);
       jpeg_stdio_src(&cinfo, infile);
       jpeg_read_header(&cinfo, TRUE);
       jpeg_start_decode(&cinfo, NULL);

       // Create PDF document
       pdf_document* doc = pdf_new_document();

       // Read and process JPEG data
       uint8_t buffer[1024];
       while (JSAMPLE * buffer_src = jpeg_read_scanlines(&cinfo, buffer, 1)) {
           pdf_page* page = pdf_get_page(doc, 0);
           size_t len = fread(buffer, sizeof(JSAMPLE), 1024, infile);
           if (len != 1024) break; // End of file
           pdf_set_rgb_colorspace(page->colorspace);
           pdf_set_device_rgb(page->colorspace, buffer, len / 3);
       }

       // Save and close PDF document
       char outputFileName[] = "output.pdf";
       pdf_save_to_file(doc, outputFileName);
       pdf_destroy_document(doc);

       // Cleanup JPEG data
       jpeg_finish_decode(&cinfo);
       jpeg_destroy_decompress(&cinfo);
       fclose(infile);
   }
   ```

