    if (++pool->alloc_count == pool->capacity) {
        // Extend memory pool when needed, implement using realloc or custom memory management functions
    }
    return buf;
}

void mempool_free(struct mempool *pool, void *ptr) {
    --pool->alloc_count;
}

void append_slash_if_needed(char* url, size_t url_len, const char* delim, size_t max_url_len, struct mempool* mempool, Logger logger) {
    if (!url || !delim || url_len >= max_url_len) return;

    sem_wait(&mutex);
    char *new_url = mempool_alloc(mempool);
    size_t new_url_len = url_len + 1; // Including null terminator
    if (new_url_len > max_url_len) {
        sem_post(&mutex);
        log("Buffer overflow. URL too long.");
        return;
    }

    // Handle multi-byte character encoding issues here, such as UTF-8 validation and normalization

    memcpy(new_url, url, url_len);
    new_url[url_len] = *delim;
    new_url[url_len + 1] = '\0';

    sem_post(&mutex);
}
