// Function to validate and process password asynchronously
void* secure_password_processor(PasswordRequest* request) {
    sem_wait(&lock);
    bool valid = false;
    size_t len = strlen(request->password);

    // Check password length and metadata
    if (len <= request->max_len && request->metadata != NULL) {
        valid = true;
    }

    // Make request to external service
