['1. C Function (FindLargestInt):

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int data;
    struct Node *next;
} Node;

Node* createNode(int data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

void insertAtTail(Node** headRef, int data) {
    if (*headRef == NULL) {
        *headRef = createNode(data);
        return;
    }
    Node* newNode = createNode(data);
    Node* temp = *headRef;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = newNode;
}

int findLargestInt(Node* head) {
    int largest = INT_MIN;
    Node* current = head;

    while (current != NULL) {
        if (current->data > largest) {
            largest = current->data;
        }
        current = current->next;
    }
    return largest;
}

int main() {
    int num, n;
    scanf("%d", &n);

    Node* head = NULL;
    for (int i = 0; i < n; ++i) {
        scanf("%d", &num);
        insertAtTail(&head, num);
    }

    printf("Largest integer: %d\n", findLargestInt(head));
    return 0;
}
```

