public class RandomValueGenerator {
    private float min;
    private float max;

    public RandomValueGenerator(float min, float max) {
        this.min = min;
        this.max = max;
    }

    public float GetRandomFloat() {
        return new System.Random().NextFloat() * (this.max - this.min) + this.min;
    }

    public float GetRandomFloat(bool inclusive) {
        if (inclusive)
            return this.GetRandomFloat();
        else
            return (new System.Random().NextDouble() * (this.max - this.min)) + this.min;
    }

    public int GetRandomInt() {
        return (int)(this.GetRandomFloat());
    }

    public override string ToString() {
        return $"{min} to {max}";
    }
}
