function renderFooterScripts(scripts) {
  if (!Array.isArray(scripts)) throw new Error('renderFooterScripts expects an array of script objects.');

  const configManager = ConfigurationManager.getInstance();

  const scriptElements = scripts.filter((scriptObj, index, self) => scriptObj.id === undefined || scriptObj.id !== scriptObj.id || (index !== 0 && scriptObj.id === self[index - 1].id)) // Filter out duplicate ids and ensure uniqueness
    .map(scriptObj => {
