typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t memoryPoolMutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* memoryPool = NULL;
static size_t currentSize = 0, maxSize = 100000;

void initializeMemoryPool() {
    if (memoryPool != NULL) return;

    memoryPool = malloc(maxSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    currentSize = maxSize;
}

NFAPI_CRC_INDICATION_PDU_T* acquireElement() {
    pthread_mutex_lock(&memoryPoolMutex);

    if (currentSize == 0) {
        printf("Memory pool is empty.\n");
        pthread_mutex_unlock(&memoryPoolMutex);
        return NULL;
    }

    currentSize--;
    NFAPI_CRC_INDICATION_PDU_T* element = &memoryPool[currentSize];
    pthread_mutex_unlock(&memoryPoolMutex);
    return element;
}

void releaseElement(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&memoryPoolMutex);
    currentSize++;
    pthread_mutex_unlock(&memoryPoolMutex);
}

