```csharp
using System;
using System.Xml.XPath;
using System.Xml.Linq;

public static XElement GetSingleElementByXPath(string xml, string xpath)
{
    var doc = XDocument.Parse(xml);
    var elements = doc.XPathSelectElements(xpath);

    if (elements.Count() == 0) throw new ArgumentException($"No element found matching '{xpath}'");
    if (elements.Count() > 1) throw new ArgumentException($"Multiple elements found matching '{xpath}'");

    return elements.First();
}
