3. Create the main application class and configure Spring Cloud Gateway.

```java
package com.example;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.gateway.route.RouteLocator;
import org.springframework.cloud.gateway.route.builder.RouteLocatorBuilder;
import org.springframework.context.annotation.Bean;
import reactor.func.Function;

@SpringBootApplication
public class GatewayApplication {
    public static void main(String[] args) {
        SpringApplication.run(GatewayApplication.class, args);
    }

    @Bean
    public RouteLocator customRouteLocator(RouteLocatorBuilder builder) {
        Function<String, String> hostExtractor = exchange -> exchange.getRequest().getHeaders().getFirst("X-Host");

        return builder.routes()
                .route(p -> p.path("/api/**")
                        .filters(f -> f.addResponseHeader("X-Host", "service1"))
                        .uri("lb://service1"))
                .route(p -> p.path("/api2/**")
                        .filters(f -> f.circuitBreaker(c -> c.setName("service2").setFallbackUri("forward:/fallback")))
                        .uri("http://service2:8080"))
                .routeId("fallback-route")
                .path("/{**path}")
                .filters(f -> f.circuitBreaker(c -> c.setName("fallback")))
                .uri("forward:/fallback-service");
    }
}
```

