import json
class JsonObject(object):
    def __init__(self, data=None):
        if data is not None:
            self.from_json(data)

    def to_json(self):
        return json.dumps(self.__dict__)

    @staticmethod
    def from_json(cls, json_str):
        obj = cls()
        obj.__dict__.update(json.loads(json_str))
        return obj

class JsonObjectRegistry:
    def __init__(self):
        self._registry = {}

    def register(self, id, factory):
        self._registry[id] = factory

    def create(self, id, **kwargs):
        if id not in self._registry:
            raise KeyError("Invalid object ID: {}".format(id))
        return self._registry[id](**kwargs)
