    public int expires_in { get; set; }
    public string token_type { get; set; }
    public string refresh_token { get; set; }
}

public class TokenValidator
{
    private readonly JsonSchema _schema;

    public TokenValidator(string schema)
    {
        _schema = JsonSchema.Parse(schema);
    }

    public bool IsValid(AccessTokenModel token)
    {
        var validator = new JsonSchemaValidator(_schema);
        return validator.Validate(token).IsValid;
    }
}

public class DatabaseContext : DbContext
{
    // Your DbSet configurations for AccessTokenModel goes here...
}

public class DataIngestionService
{
    private readonly TokenValidator _tokenValidator;
    private readonly DatabaseContext _context;
    private readonly int _batchSize;
    private readonly TimeSpan _batchInterval;

    public DataIngestionService(TokenValidator tokenValidator, DatabaseContext context, int batchSize = 100, TimeSpan batchInterval = TimeSpan.FromSeconds(5))
    {
        _tokenValidator = tokenValidator;
        _context = context;
        _batchSize = batchSize;
        _batchInterval = batchInterval;
    }

    public void ProcessTokens(IEnumerable<string> tokens)
    {
        var batchedTokens = tokens.Chunk(_batchSize);

        ParallelOptions options = new ParallelOptions() { MaxDegreeOfParallelism = Environment.ProcessorCount };

        Parallel.ForEach(batchedTokens, options, batch =>
        {
            using (var transaction = _context.Database.BeginTransaction())
            {
                try
                {
                    var tokenModels = tokens.Select(JsonSerializer.Deserialize<AccessTokenModel>).ToList();
                    var invalidTokens = tokenModels.Where(x => !_tokenValidator.IsValid(x)).ToList();

                    _context.AddRange(tokenModels.Where(x => !invalidTokens.Contains(x)));

                    if (invalidTokens.Any())
                        throw new Exception($"Invalid tokens found: {string.Join(", ", invalidTokens)}");

                    _context.SaveChanges();
                    transaction.Commit();
                }
                catch (Exception ex)
                {
                    transaction.Rollback();
                    // Log exception here...
                }
            }
        });
    }
}
```

This implementation provides a basic data ingestion pipeline that processes JSON-encoded OAuth2 access token responses, validates the data, and stores it in a database. It uses batch processing to handle multiple tokens concurrently, ensuring thread safety and efficient memory utilization. The solution leverages asynchronous programming techniques with Parallel.ForEach and implements an adjustable batch size and interval based on current system load and available resources.

To further expand this implementation, consider integrating anomaly detection mechanisms, caching strategies, error handling and recovery mechanisms, and other components as needed for your specific use case.']

