['1. C Function: `initializeConnectionManager`

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// ConnectionInfo structure definition
typedef struct {
    void *handle;
    sem_t latencyMonitor;
    // Other members...
} ConnectionInfo;

sem_t mutex;
int arraySize = 0;
ConnectionInfo* connectionManager;

void* initConnection(int index) {
    // Initialize individual connection here using the external packet capture library
    // ...

    sem_init(&connectionManager[index].latencyMonitor, 0, 1);

    return NULL;
}

void handleLatencySpikes(ConnectionInfo* connInfo) {
    // Handle latency spikes here
}

void resizeConnectionManager() {
    if (arraySize == 0) arraySize = 1;

    ConnectionInfo *temp = realloc(connectionManager, arraySize * sizeof(ConnectionInfo));

    if (!temp) {
        // Handle memory allocation failure gracefully
        fprintf(stderr, "Memory allocation error\n");
        return;
    }

    connectionManager = temp;
}

void initializeConnectionManager() {
    sem_init(&mutex, 0, 1);

    if (connectionManager) free(connectionManager);

    resizeConnectionManager();

    pthread_t threadIds[arraySize];

    for (int i = 0; i < arraySize; ++i) {
        connectionManager[i].handle = NULL;
        connectionManager[i].latencyMonitor = sem_init(connectionManager[i].latencyMonitor, 0, 1);

        if (pthread_create(&threadIds[i], NULL, initConnection, (void*) i) != 0) {
            fprintf(stderr, "Thread creation error\n");
            return;
        }
    }

    for (int i = 0; i < arraySize; ++i) {
        pthread_join(threadIds[i], NULL);
    }
}
```

2. JavaScript Module: `footerScriptManager`

```javascript
import fetch from 'node-fetch';

class FooterScriptManager {
  constructor() {
    this.scripts = [];
    this.lazyLoadedScripts = [];
  }

  addScript(src, mimeType, callback) {
    const scriptTag = document.createElement('script');
    scriptTag.setAttribute('type', mimeType);
    scriptTag.setAttribute('data-src', src);
    // Add lazy loading strategy here...

    this.scripts.push(scriptTag);

    if (/\btext\/javascript|module|\bapplication\/ld\+json/.test(mimeType)) {
      this.lazyLoadedScripts.push((callback || this.loadLazyScript).bind(this, scriptTag));
    }
  }

  loadLazyScript(scriptTag) {
    fetch(scriptTag.getAttribute('data-src'))
      .then(response => {
        if (!response.ok) throw new Error(`HTTP error ${response.status}`);
        return response.text();
      })
      .then(data => scriptTag.textContent = data)
      .catch(error => console.error('Error loading script:', error))
      .finally(() => {
        document.head.appendChild(scriptTag);
      });
  }

  loadScripts() {
    for (const script of this.scripts) {
      if (this.lazyLoadedScripts.includes(script)) {
        // Add CORS preflight request handling here...
        this.lazyLoadedScripts.splice(this.lazyLoadedScripts.indexOf(script), 1)(script);
      } else {
        document.head.appendChild(script);
      }
    }
  }
}

export default FooterScriptManager;
```']

