```python
import psycopg2
import hashlib
from SecureDataProcessor import DataTransformer, Encryptor

def process_data(database_url, query, storage_url, transform_rules, key):
    # Connect to the database and execute the query
    conn = psycopg2.connect(database_url)
    cursor = conn.cursor()
    cursor.execute(query)
    records_count = cursor.rowcount

    # Create DataTransformer instance with defined transform rules and SecureDataProcessor key
    dt = DataTransformer(transform_rules, Encryptor(key))

    # Process each record from the query result
    for row in cursor:
        dt.apply_transformation(*row)

    # Store processed data securely using StorageProvider instance
    storage_provider = StorageProvider(storage_url)
    metadata = dt.get_metadata()
    storage_provider.store(dt.get_processed_data(), metadata)

    conn.close()
    return records_count, metadata
